export function composerLines(input: { count: number }): string {
  const count = formatNumber(input.count);
  switch (currentLanguage()) {
    case "en-XA":
      switch (pluralCategory(input.count, "en")) {
        case "one":
          return `[${count} ļîñé ~~]`;
        default:
          return `[${count} ļîñéš ~~]`;
      }
    case "ar-XB":
      switch (pluralCategory(input.count, "en")) {
        case "one":
          return `${count}\u202e line\u202c`;
        default:
          return `${count}\u202e lines\u202c`;
      }
  }
  switch (pluralCategory(input.count)) {
    case "one":
      return `${count} line`;
    default:
      return `${count} lines`;
  }
}

